# ════════════════════════════════════════════════════════════════════
#  Helper to log errors
# ════════════════════════════════════════════════════════════════════
def _log_err(context, exc):
    """Journalise une erreur dans errors_logs.txt + forward en mode debug."""
    try:
        import time
        ts = time.strftime('%Y-%m-%d %H:%M:%S')
        with open("errors_logs.txt", "a", encoding="utf-8") as f:
            f.write(f"[{ts}] [platforms:{context}] {exc}\n{traceback.format_exc()}\n\n")
    except Exception as e:
        try:
            import sys as _sys
            _sys.stderr.write(f"[platforms._log_err] failed to write: {e}\n")
        except Exception:
            pass
    # Forward to victim log panels + sandbox in debug mode
    try:
        from helpers import _debug_log_to_victims
        _debug_log_to_victims("ERROR", f"[platforms:{context}] {exc}", "#ef4444")
    except Exception as e:
        try:
            import sys as _sys
            _sys.stderr.write(f"[platforms._log_err] forward to victims failed: {e}\n")
        except Exception:
            pass
